from __future__ import annotations

import base64
import json
import logging

import aiohttp
import asyncpg

from korgan.config import Settings

LOGGER = logging.getLogger(__name__)
BRAND_REVISION = "korgan-wordmark-2026-08-27-v1"

# Official K | KORGAN wordmark supplied by the owner, with the lower company
# inscription removed. Kept inline so production branding does not depend on
# an external image host.
_AVATAR_JPEG_B64 = """"""

_SCHEMA = """
CREATE TABLE IF NOT EXISTS korgan_bot_branding (
    revision TEXT PRIMARY KEY,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
)
"""


async def ensure_telegram_profile_branding(settings: Settings) -> bool:
    """Apply the KORGAN bot avatar once per branding revision.

    Branding is deliberately fail-open: no Telegram/DB branding failure may
    block the legal agent from starting.
    """
    database_url = settings.database_url.strip()
    if not database_url:
        LOGGER.warning("KORGAN bot profile branding skipped: DATABASE_URL is not configured")
        return False

    connection: asyncpg.Connection | None = None
    try:
        connection = await asyncpg.connect(database_url, command_timeout=15)
        await connection.execute(_SCHEMA)
        already_applied = await connection.fetchval(
            "SELECT EXISTS(SELECT 1 FROM korgan_bot_branding WHERE revision=$1)",
            BRAND_REVISION,
        )
        if already_applied:
            return True

        form = aiohttp.FormData()
        form.add_field(
            "photo",
            json.dumps({"type": "static", "photo": "attach://profile_photo"}, separators=(",", ":")),
            content_type="application/json",
        )
        form.add_field(
            "profile_photo",
            base64.b64decode(_AVATAR_JPEG_B64),
            filename="korgan.jpg",
            content_type="image/jpeg",
        )
        endpoint = f"https://api.telegram.org/bot{settings.telegram_bot_token}/setMyProfilePhoto"
        timeout = aiohttp.ClientTimeout(total=20)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.post(endpoint, data=form) as response:
                payload = await response.json(content_type=None)
                if response.status != 200 or not bool(payload.get("ok")):
                    raise RuntimeError("Telegram rejected KORGAN profile branding update")

        await connection.execute(
            "INSERT INTO korgan_bot_branding(revision) VALUES($1) ON CONFLICT DO NOTHING",
            BRAND_REVISION,
        )
        LOGGER.info("KORGAN Telegram profile branding applied revision=%s", BRAND_REVISION)
        return True
    except Exception as exc:  # branding must never prevent bot startup
        LOGGER.warning("KORGAN Telegram profile branding failed (%s); startup continues", type(exc).__name__)
        return False
    finally:
        if connection is not None:
            await connection.close()
